// Check of the active modules' queue (scripts/check_templates.sh): include/active_demo/active.hpp of
// tests/fixtures/active.scaffold.yaml, generated by a C++11-or-later set. Prints "ok" or the failed check.
#include <active_demo/active.hpp>

#include <atomic>
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

using active_demo::ActiveError;
using active_demo::ActiveQueue;
using std::chrono::milliseconds;

namespace {

int failures = 0;

void expect(bool ok, const char* what)
{
    if (!ok) {
        std::cerr << "FAILED: " << what << '\n';
        ++failures;
    }
}

struct Busy {
    std::string reason;
};

} // namespace

int main()
{
    // Calls with a result run on the queue's thread and give their result back.
    {
        ActiveQueue q(8, milliseconds(1000), ActiveQueue::Overflow::block);
        const std::thread::id caller = std::this_thread::get_id();
        std::thread::id ran;
        const int r = q.call([&] {
            ran = std::this_thread::get_id();
            return 41 + 1;
        });
        expect(r == 42, "call returns the result");
        expect(ran != caller, "call runs on the module's thread");
        std::string head;
        q.call([&] { head = "out"; });
        expect(head == "out", "call sets out parameters");
    }
    // Exceptions come back to the caller, typed.
    {
        ActiveQueue q(8, milliseconds(1000), ActiveQueue::Overflow::block);
        bool caught = false;
        try {
            q.call([]() -> int { throw Busy{"full"}; });
        } catch (const Busy& e) {
            caught = e.reason == "full";
        }
        expect(caught, "call rethrows the exception of the handler");
    }
    // Posted calls run in their order; the destructor runs those still queued.
    {
        std::vector<int> order;
        {
            ActiveQueue q(64, milliseconds(1000), ActiveQueue::Overflow::block);
            for (int i = 0; i < 20; ++i) q.post([&order, i] { order.push_back(i); });
        }
        bool sorted = order.size() == 20;
        for (int i = 0; sorted && i < 20; ++i) sorted = order[i] == i;
        expect(sorted, "posted calls run in order, all of them");
    }
    // A call not started within the timeout fails, and never runs.
    {
        std::atomic<bool> late(false);
        {
            ActiveQueue q(8, milliseconds(50), ActiveQueue::Overflow::block);
            q.post([] { std::this_thread::sleep_for(milliseconds(200)); });
            bool timedOut = false;
            try {
                q.call([&] { late = true; });
            } catch (const ActiveError&) {
                timedOut = true;
            }
            expect(timedOut, "call times out");
        }
        expect(!late, "a call given up does not run");
    }
    // A full queue: error throws, drop loses the call.
    {
        ActiveQueue q(1, milliseconds(1000), ActiveQueue::Overflow::error);
        std::atomic<bool> go(false);
        q.post([&] {
            while (!go) std::this_thread::sleep_for(milliseconds(1));
        });
        std::this_thread::sleep_for(milliseconds(20)); // the first job is running
        q.post([] {});
        bool full = false;
        try {
            q.post([] {});
        } catch (const ActiveError&) {
            full = true;
        }
        go = true;
        expect(full, "overflow error throws on a full queue");
    }
    {
        std::atomic<int> ran(0);
        {
            ActiveQueue q(1, milliseconds(1000), ActiveQueue::Overflow::drop);
            std::atomic<bool> go(false);
            q.post([&] {
                while (!go) std::this_thread::sleep_for(milliseconds(1));
            });
            std::this_thread::sleep_for(milliseconds(20));
            q.post([&] { ++ran; });
            q.post([&] { ++ran; });
            go = true;
        }
        expect(ran == 1, "overflow drop loses the call");
    }
    // A call from the thread itself runs at once (no deadlock).
    {
        ActiveQueue q(8, milliseconds(1000), ActiveQueue::Overflow::block);
        const int r = q.call([&] { return q.call([] { return 7; }); });
        expect(r == 7, "a call from the module's thread runs at once");
    }
    if (failures) return EXIT_FAILURE;
    std::cout << "ok\n";
    return EXIT_SUCCESS;
}
